//! Differential test: outputs of the TypeScript utils (generated by running the reference
//! implementation on a pseudo-random corpus) must match the Rust port exactly.

use pi_tui::utils::*;
use serde_json::Value;

fn s(v: &Value) -> &str {
    v.as_str().unwrap()
}

#[test]
fn utils_match_typescript_reference() {
    let data: Value = serde_json::from_str(include_str!("fixtures/utils_cases.json")).unwrap();
    let widths = [1usize, 2, 3, 5, 8, 13, 40];
    let mut failures = Vec::new();
    for case in data.as_array().unwrap() {
        let text = s(&case["s"]);
        let single = text.replace('\n', "");
        let mut check = |what: String, got: Value, want: &Value| {
            if &got != want {
                failures.push(format!("{what} for {text:?}: got {got:?}, want {want:?}"));
            }
        };
        check("width".into(), Value::from(visible_width(text)), &case["width"]);
        check("strip".into(), Value::from(strip_terminal_sequences(text)), &case["strip"]);
        check("normalize".into(), Value::from(normalize_terminal_output(text)), &case["normalize"]);
        check("bg".into(), Value::from(get_active_background_ansi(text)), &case["bg"]);
        for (i, w) in widths.iter().enumerate() {
            check(format!("wrap {w}"), Value::from(wrap_text_with_ansi(text, *w)), &case["wrap"][i]);
            let t = &case["trunc"][i];
            check(format!("trunc {w}"), Value::from(truncate_to_width(&single, *w, "...", false)), &t[0]);
            check(format!("trunc pad {w}"), Value::from(truncate_to_width(&single, *w, "…", true)), &t[1]);
            check(format!("trunc empty {w}"), Value::from(truncate_to_width(&single, *w, "", false)), &t[2]);
        }
        for (i, (a, b, c)) in [(0, 3, false), (2, 5, true), (1, 10, false), (4, 4, true)].iter().enumerate() {
            check(format!("slice {a} {b} {c}"), Value::from(slice_by_column(&single, *a, *b, *c)), &case["slice"][i]);
        }
        for (i, (a, b, c, d)) in [(2, 5, 3, false), (0, 1, 20, true), (4, 4, 0, false)].iter().enumerate() {
            let seg = extract_segments(&single, *a, *b, *c, *d);
            let want = &case["seg"][i];
            check(format!("seg.before {i}"), Value::from(seg.before), &want["before"]);
            check(format!("seg.beforeWidth {i}"), Value::from(seg.before_width), &want["beforeWidth"]);
            check(format!("seg.after {i}"), Value::from(seg.after), &want["after"]);
            check(format!("seg.afterWidth {i}"), Value::from(seg.after_width), &want["afterWidth"]);
        }
        for (i, c) in [0usize, 3, 7].iter().enumerate() {
            let got = get_osc8_link_at_column(&single, *c).map(Value::from).unwrap_or(Value::Null);
            check(format!("osc {c}"), got, &case["osc"][i]);
            let got = get_grapheme_cell_range(&single, *c)
                .map(|r| serde_json::json!({"start": r.start, "end": r.end}))
                .unwrap_or(Value::Null);
            check(format!("cell {c}"), got, &case["cell"][i]);
        }
    }
    if !failures.is_empty() {
        panic!("{} mismatches:\n{}", failures.len(), failures.iter().take(15).cloned().collect::<Vec<_>>().join("\n"));
    }
}
